package com.voxalocal.offlinespeech.engine

import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlin.math.log10
import kotlin.math.sqrt

data class CustomVocabularyEntry(
    val id: String,
    val dialectWord: String,
    val phoneticPattern: String,
    val ipaNotation: String,
    val dialectRegion: String,
    val standardGloss: String,
    val acousticAliases: List<String>,
    val boostWeight: Float = 2.0f
)

data class PhoneticRule(
    val id: String,
    val ruleName: String,
    val sourcePhoneme: String,
    val targetOrthography: String,
    val dialectRegion: String,
    val enabled: Boolean = true
)

class OfflineSpeechEngine(
    private val sampleRateHz: Int = 16000
) {
    private val _partialHypothesis = MutableStateFlow("")
    val partialHypothesis: StateFlow<String> = _partialHypothesis.asStateFlow()

    private val _committedTranscript = MutableStateFlow("")
    val committedTranscript: StateFlow<String> = _committedTranscript.asStateFlow()

    private var vocabularyEntries: List<CustomVocabularyEntry> = emptyList()
    private var phoneticRules: List<PhoneticRule> = emptyList()

    fun configureLanguageModel(
        vocabulary: List<CustomVocabularyEntry>,
        rules: List<PhoneticRule>
    ) {
        this.vocabularyEntries = vocabulary.sortedByDescending { it.boostWeight }
        this.phoneticRules = rules.filter { it.enabled }
    }

    fun applyCustomPhoneticPipeline(rawPhoneticTokens: String): String {
        if (rawPhoneticTokens.isBlank()) return ""
        var transformed = rawPhoneticTokens.trim()

        for (rule in phoneticRules) {
            if (rule.sourcePhoneme.isNotEmpty()) {
                transformed = transformed.replace(
                    Regex(Regex.escape(rule.sourcePhoneme), RegexOption.IGNORE_CASE),
                    rule.targetOrthography
                )
            }
        }

        val tokens = transformed.split(Regex("\\s+"))
        return tokens.joinToString(" ") { rawToken ->
            val clean = rawToken.lowercase().trim(',', '.', '?', '!')
            val matched = vocabularyEntries.firstOrNull { entry ->
                entry.dialectWord.equals(clean, ignoreCase = true) ||
                entry.phoneticPattern.equals(clean, ignoreCase = true) ||
                entry.acousticAliases.any { alias -> alias.equals(clean, ignoreCase = true) }
            }
            matched?.dialectWord ?: rawToken
        }
    }
}

package com.voxalocal.offlinespeech.data

import android.content.Context
import org.json.JSONArray
import org.json.JSONObject
import java.io.File

class LocalStorageRepository(private val context: Context) {
    private val recordingsDir: File
        get() = File(context.filesDir, "offline_recordings").apply { mkdirs() }

    private val transcriptionsFile: File
        get() = File(context.filesDir, "saved_transcriptions.json")

    fun createNewAudioFile(sessionId: String): File =
        File(recordingsDir, "voxalocal_${sessionId}.wav")

    fun deleteTranscriptionAndAudio(recordId: String) {
        val wavFile = File(recordingsDir, "voxalocal_${recordId}.wav")
        if (wavFile.exists()) wavFile.delete()
    }
}

